    let nSample = textureSample(normalTex, normalSampler, uv).rgb;
    let nTangent = nSample * 2.0 - vec3f(1.0);
    let worldNormal = normalize(T * nTangent.x + B * nTangent.y + N * nTangent.z);
    return worldNormal;
